72	/* ─── Webflow CSS design tokens ────────────────────────────────────────────── */
73	:root {
74	  --blue: #082753;
75	  --white: white;
76	  --black: black;
77	  --para-small: 16px;
78	  --h2: 40px;
79	  --h1: 3.125rem;
