95	  --muted: #f7f7f8;
96	  --muted-foreground: #6b7280;
97	  --accent: #21cfff;
98	  --accent-foreground: #082753;
99	  --destructive: #ef4444;
100	  --border: #e5e7eb;
101	  --input: #e5e7eb;
102	  --ring: #21cfff;
103	  --chart-1: #21cfff;
104	  --chart-2: #019ae6;
105	  --chart-3: #FFEB85;
106	  --chart-4: #082753;
