1	"use client";
2	
3	import { useState, useMemo } from "react";
4	import { PORTFOLIO_ITEMS, PORTFOLIO_CATEGORIES } from "@/lib/constants/portfolio";
5	import { PortfolioFilter } from "./portfolio-filter";
6	import { PortfolioCard } from "./portfolio-card";
7	import styles from "./portfolio-grid.module.css";
8	
9	export function PortfolioGrid() {
10	  const [activeCategory, setActiveCategory] = useState<string>("all");
11	  const [searchQuery, setSearchQuery] = useState<string>("");
12	
13	  const filtered = useMemo(() => {
14	    return PORTFOLIO_ITEMS.filter((item) => {
15	      const matchesCategory =
16	        activeCategory === "all" || item.category === activeCategory;
17	      const normalizedQuery = searchQuery.trim().toLowerCase();
18	      const matchesSearch =
19	        normalizedQuery === "" ||
20	        item.name.toLowerCase().includes(normalizedQuery) ||
21	        item.category.toLowerCase().includes(normalizedQuery);
22	      return matchesCategory && matchesSearch;
23	    });
24	  }, [activeCategory, searchQuery]);
25	
26	  return (
27	    <section className={styles.section}>
28	      <div className={styles.container}>
29	        <PortfolioFilter
30	          categories={PORTFOLIO_CATEGORIES}
31	          active={activeCategory}
32	          search={searchQuery}
33	          onCategoryChange={setActiveCategory}
34	          onSearchChange={setSearchQuery}
35	        />
36	
37	        <p className={styles.resultCount}>
38	          {filtered.length === 1
39	            ? "1 project"
40	            : `${filtered.length} projects`}
41	          {(activeCategory !== "all" || searchQuery.trim() !== "") && (
42	            <button
43	              type="button"
44	              onClick={() => {
45	                setActiveCategory("all");
46	                setSearchQuery("");
47	              }}
48	              className={styles.resetBtn}
49	            >
50	              Clear filters
51	            </button>
52	          )}
53	        </p>
54	
55	        {filtered.length === 0 ? (
56	          <div className={styles.emptyState}>
57	            <div className={styles.emptyIcon} aria-hidden="true">
58	              <svg
59	                xmlns="http://www.w3.org/2000/svg"
60	                width="48"
61	                height="48"
62	                viewBox="0 0 24 24"
63	                fill="none"
64	                stroke="currentColor"
65	                strokeWidth="1.25"
66	                strokeLinecap="round"
67	                strokeLinejoin="round"
68	              >
69	                <rect x="3" y="3" width="7" height="7" rx="1" />
70	                <rect x="14" y="3" width="7" height="7" rx="1" />
71	                <rect x="3" y="14" width="7" height="7" rx="1" />
72	                <rect x="14" y="14" width="7" height="7" rx="1" />
73	              </svg>
74	            </div>
75	            <h3 className={styles.emptyTitle}>No projects found</h3>
76	            <p className={styles.emptyDesc}>
77	              Try a different filter or search term.
78	            </p>
79	            <button
80	              type="button"
81	              onClick={() => {
82	                setActiveCategory("all");
83	                setSearchQuery("");
84	              }}
85	              className={styles.emptyBtn}
86	            >
87	              Show all projects
88	            </button>
89	          </div>
90	        ) : (
91	          <ul className={styles.grid} role="list">
92	            {filtered.map((item) => (
93	              <li key={item.slug}>
94	                <PortfolioCard item={item} />
95	              </li>
96	            ))}
97	          </ul>
98	        )}
99	      </div>
100	    </section>
101	  );
102	}
