1	import Image from "next/image";
2	import Link from "next/link";
3	import type { PortfolioItem } from "@/types/portfolio";
4	import styles from "./portfolio-card.module.css";
5	
6	const CATEGORY_LABELS: Record<string, string> = {
7	  shopify: "Shopify",
8	  wordpress: "WordPress",
9	};
10	
11	export function PortfolioCard({ item }: { item: PortfolioItem }) {
12	  const inner = (
13	    <article className={styles.card}>
14	      <div className={styles.imageWrapper}>
15	        <Image
16	          src={item.featuredImage}
17	          alt={`${item.name} — Boldteq portfolio project`}
18	          fill
19	          sizes="(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 33vw"
20	          className={styles.image}
21	          loading="lazy"
22	        />
23	        <span className={`${styles.badge} ${styles[`badge--${item.category}`]}`}>
24	          {CATEGORY_LABELS[item.category]}
25	        </span>
26	      </div>
27	      <div className={styles.footer}>
28	        <p className={styles.name}>{item.name}</p>
29	        {item.hasDetailPage && (
30	          <span className={styles.viewLink} aria-hidden="true">
31	            View project →
32	          </span>
33	        )}
34	      </div>
35	    </article>
36	  );
37	
38	  if (item.hasDetailPage) {
39	    return (
40	      <Link
41	        href={`/our-works/${item.slug}`}
42	        className={styles.linkWrapper}
43	        aria-label={`View ${item.name} project`}
44	      >
45	        {inner}
46	      </Link>
47	    );
48	  }
49	
50	  return <div className={styles.linkWrapper}>{inner}</div>;
51	}
