export interface BlogPost {
  title: string;
  slug: string;
  image: string;
  shortDescription: string;
  category: string;
}

export interface BlogCategory {
  slug: string;
  name: string;
}

import Image from "next/image";
import Link from "next/link";
import styles from "./blog-hero.module.css";

const STAT_BADGES = [
  {
    icon: "/images/webflow/Layer_1-14.svg",
    label: "Built for Agencies",
  },
  {
    icon: "/images/webflow/Layer_1-3.svg",
    label: "White-Label Expertise",
  },
  {
    icon: "/images/webflow/Layer_1-15.svg",
    label: "Execution-Focused",
  },
];

export function BlogHero() {
  return (
    <section className={styles.section}>
      <div className={styles.container}>
        <h1 className={styles.heading}>
          Insights on Scaling Agencies with White-Label Delivery
        </h1>
        <p className={styles.subtitle}>
          Practical insights on white-label outsourcing, agency growth, web
          delivery systems, and conversion-focused execution — written for
          agencies that want to scale without adding headcount.
        </p>

        <div className={styles.badges}>
          {STAT_BADGES.map((badge) => (
            <div key={badge.label} className={styles.badge}>
              <Image
                src={badge.icon}
                alt=""
                width={20}
                height={20}
                className={styles.badgeIcon}
                aria-hidden="true"
              />
              <span className={styles.badgeLabel}>{badge.label}</span>
            </div>
          ))}
        </div>

        <Link href="/how-it-works" className={styles.cta}>
          Explore How It Works
        </Link>
      </div>
    </section>
  );
}

/* ============================================================
   BlogHero — blog-hero.module.css
   ============================================================ */

.section {
  background-color: #092245;
  padding: 80px 5% 72px;
  text-align: center;
}

.container {
  max-width: 56rem;
  margin-left: auto;
  margin-right: auto;
}

.heading {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: clamp(1.75rem, 4vw, 3rem);
  font-weight: 700;
  line-height: 1.15;
  color: #ffffff;
  margin: 0 0 20px;
}

.subtitle {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 17px;
  line-height: 1.7;
  color: rgba(255, 255, 255, 0.65);
  margin: 0 auto 40px;
  max-width: 46rem;
}

.badges {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-bottom: 36px;
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background-color: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 999px;
  padding: 8px 18px;
}

.badgeIcon {
  flex-shrink: 0;
  filter: brightness(0) invert(1);
}

.badgeLabel {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 13px;
  font-weight: 600;
  color: #ffffff;
  white-space: nowrap;
}

.cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(90deg, #21cfff, #019ae6);
  color: #ffffff;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 15px;
  font-weight: 700;
  border-radius: 999px;
  padding: 12px 32px;
  text-decoration: none;
  transition: filter 0.15s ease;
}

.cta:hover {
  filter: brightness(1.08);
}

/* ============================================================
   max-width: 640px (mobile)
   ============================================================ */
@media screen and (max-width: 640px) {
  .section {
    padding: 64px 5% 56px;
  }

  .badges {
    gap: 8px;
  }

  .badge {
    padding: 7px 14px;
  }
}

import Image from "next/image";
import type { BlogPost } from "@/types/blog";
import styles from "./blog-card.module.css";

const CATEGORY_LABELS: Record<string, string> = {
  cro: "CRO",
  shopify: "Shopify",
  "ui-ux-design": "UI/UX Design",
  "web-development": "Web Development",
  "white-label-outsourcing": "White-Label & Outsourcing",
  wordpress: "WordPress",
};

export function BlogCard({ post }: { post: BlogPost }) {
  return (
    <article className={styles.card}>
      <div className={styles.imageWrapper}>
        <Image
          src={post.image}
          alt={`${post.title} — Boldteq blog`}
          fill
          sizes="(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 33vw"
          className={styles.image}
          loading="lazy"
        />
        <span className={styles.badge}>
          {CATEGORY_LABELS[post.category] ?? post.category}
        </span>
      </div>
      <div className={styles.body}>
        <h3 className={styles.title}>{post.title}</h3>
        <p className={styles.description}>{post.shortDescription}</p>
      </div>
    </article>
  );
}

/* ============================================================
   BlogCard — blog-card.module.css
   ============================================================ */

.card {
  background-color: #ffffff;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.08);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  height: 100%;
  display: flex;
  flex-direction: column;
}

.card:hover {
  transform: translateY(-4px) scale(1.01);
  box-shadow: 0 8px 24px rgba(9, 34, 69, 0.14);
}

/* 16:9 aspect ratio image container */
.imageWrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  background-color: #f5f7fa;
  flex-shrink: 0;
}

.image {
  object-fit: cover;
  transition: transform 0.3s ease;
}

.card:hover .image {
  transform: scale(1.04);
}

/* Category badge — top-left overlay */
.badge {
  position: absolute;
  top: 12px;
  left: 12px;
  z-index: 1;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  border-radius: 6px;
  padding: 4px 10px;
  line-height: 1.4;
  background-color: #dbeafe;
  color: #1e40af;
}

/* Card body */
.body {
  padding: 18px 20px 22px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  flex: 1;
}

.title {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 16px;
  font-weight: 700;
  color: #092245;
  margin: 0;
  line-height: 1.4;
}

.description {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 14px;
  line-height: 1.65;
  color: #6b7280;
  margin: 0;
}

"use client";

import { useState, useMemo } from "react";
import { BLOG_POSTS, BLOG_CATEGORIES } from "@/lib/constants/blog";
import { BlogCard } from "./blog-card";
import styles from "./blog-grid.module.css";

export function BlogGrid() {
  const [activeCategory, setActiveCategory] = useState<string>("all");
  const [searchQuery, setSearchQuery] = useState<string>("");

  const filtered = useMemo(() => {
    return BLOG_POSTS.filter((post) => {
      const matchesCategory =
        activeCategory === "all" || post.category === activeCategory;
      const normalizedQuery = searchQuery.trim().toLowerCase();
      const matchesSearch =
        normalizedQuery === "" ||
        post.title.toLowerCase().includes(normalizedQuery) ||
        post.shortDescription.toLowerCase().includes(normalizedQuery) ||
        post.category.toLowerCase().includes(normalizedQuery);
      return matchesCategory && matchesSearch;
    });
  }, [activeCategory, searchQuery]);

  return (
    <section className={styles.section}>
      <div className={styles.container}>
        {/* Filters + Search */}
        <div className={styles.controls}>
          <div className={styles.filters} role="group" aria-label="Filter by category">
            {BLOG_CATEGORIES.map((cat) => (
              <button
                key={cat.slug}
                type="button"
                onClick={() => setActiveCategory(cat.slug)}
                className={`${styles.filterBtn} ${activeCategory === cat.slug ? styles.filterBtnActive : ""}`}
                aria-pressed={activeCategory === cat.slug}
              >
                {cat.name}
              </button>
            ))}
          </div>

          <div className={styles.searchWrapper}>
            <span className={styles.searchIcon} aria-hidden="true">
              <svg
                xmlns="http://www.w3.org/2000/svg"
                width="16"
                height="16"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <circle cx="11" cy="11" r="8" />
                <line x1="21" y1="21" x2="16.65" y2="16.65" />
              </svg>
            </span>
            <input
              type="search"
              placeholder="Search articles..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className={styles.searchInput}
              aria-label="Search blog articles"
            />
            {searchQuery && (
              <button
                type="button"
                onClick={() => setSearchQuery("")}
                className={styles.clearBtn}
                aria-label="Clear search"
              >
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  width="14"
                  height="14"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <line x1="18" y1="6" x2="6" y2="18" />
                  <line x1="6" y1="6" x2="18" y2="18" />
                </svg>
              </button>
            )}
          </div>
        </div>

        {/* Result count */}
        <p className={styles.resultCount}>
          {filtered.length === 1 ? "1 article" : `${filtered.length} articles`}
          {(activeCategory !== "all" || searchQuery.trim() !== "") && (
            <button
              type="button"
              onClick={() => {
                setActiveCategory("all");
                setSearchQuery("");
              }}
              className={styles.resetBtn}
            >
              Clear filters
            </button>
          )}
        </p>

        {/* Grid or empty state */}
        {filtered.length === 0 ? (
          <div className={styles.emptyState}>
            <div className={styles.emptyIcon} aria-hidden="true">
              <svg
                xmlns="http://www.w3.org/2000/svg"
                width="48"
                height="48"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="1.25"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
                <polyline points="14 2 14 8 20 8" />
                <line x1="16" y1="13" x2="8" y2="13" />
                <line x1="16" y1="17" x2="8" y2="17" />
                <polyline points="10 9 9 9 8 9" />
              </svg>
            </div>
            <h3 className={styles.emptyTitle}>No articles found</h3>
            <p className={styles.emptyDesc}>
              Try a different filter or search term.
            </p>
            <button
              type="button"
              onClick={() => {
                setActiveCategory("all");
                setSearchQuery("");
              }}
              className={styles.emptyBtn}
            >
              Show all articles
            </button>
          </div>
        ) : (
          <ul className={styles.grid} role="list">
            {filtered.map((post) => (
              <li key={post.slug}>
                <BlogCard post={post} />
              </li>
            ))}
          </ul>
        )}
      </div>
    </section>
  );
}

