.section {
  background-color: #f5f7fa;
  padding: 64px 5% 80px;
}

.container {
  max-width: 80rem;
  margin-left: auto;
  margin-right: auto;
}

/* Controls row: filters + search */
.controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 16px;
  margin-bottom: 36px;
}

/* Filter pill row */
.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.filterBtn {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 14px;
  font-weight: 600;
  color: #092245;
  background-color: #ffffff;
  border: 1.5px solid #e5e7eb;
  border-radius: 999px;
  padding: 8px 20px;
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease;
  line-height: 1.4;
}

.filterBtn:hover:not(.filterBtnActive) {
  background-color: #ecf7fd;
  border-color: #019ae6;
  color: #019ae6;
}

.filterBtnActive {
  background: linear-gradient(90deg, #21cfff, #019ae6);
  border-color: transparent;
  color: #ffffff;
}

/* Search input */
.searchWrapper {
  position: relative;
  display: flex;
  align-items: center;
  margin-left: auto;
}

.searchIcon {
  position: absolute;
  left: 12px;
  color: #6b7280;
  display: flex;
  align-items: center;
  pointer-events: none;
}

.searchInput {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 14px;
  color: #092245;
  background-color: #ffffff;
  border: 1.5px solid #e5e7eb;
  border-radius: 999px;
  padding: 8px 36px 8px 36px;
  width: 220px;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.searchInput::placeholder {
  color: #9ca3af;
}

.searchInput:focus {
  border-color: #21cfff;
  box-shadow: 0 0 0 3px rgba(33, 207, 255, 0.15);
}

.searchInput::-webkit-search-cancel-button {
  display: none;
}

.clearBtn {
  position: absolute;
  right: 12px;
  background: none;
  border: none;
  padding: 0;
  display: flex;
  align-items: center;
  color: #6b7280;
  cursor: pointer;
  transition: color 0.15s ease;
}

.clearBtn:hover {
  color: #092245;
}

/* Result count row */
.resultCount {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 14px;
  color: #6b7280;
  margin-bottom: 24px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.resetBtn {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 13px;
  font-weight: 600;
  color: #019ae6;
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.resetBtn:hover {
  color: #092245;
}

/* 3-column responsive grid */
.grid {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

/* Empty state */
.emptyState {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 80px 24px;
  text-align: center;
}

.emptyIcon {
  width: 72px;
  height: 72px;
  border-radius: 16px;
  background-color: #ecf7fd;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #019ae6;
  margin-bottom: 20px;
}

.emptyTitle {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 18px;
  font-weight: 700;
  color: #092245;
  margin: 0 0 8px;
}

.emptyDesc {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 15px;
  color: #6b7280;
  margin: 0 0 24px;
  max-width: 320px;
}

.emptyBtn {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 14px;
  font-weight: 700;
  color: #ffffff;
  background: linear-gradient(90deg, #21cfff, #019ae6);
  border: none;
  border-radius: 999px;
  padding: 10px 24px;
  cursor: pointer;
  transition: filter 0.15s ease;
}

